  it('forwards only limit and before, never a client userId', () => {
    const before = {updatedAt: '2026-01-01T00:05:00.000Z', sessionId: 's3'};

    expect(validateMessage({type: 'list_sessions', limit: 10, before, userId: 'u2'})).toEqual({
      valid: true,
      data: {type: 'list_sessions', limit: 10, before},
    });
  });

  it.each([
    ['a string limit', {limit: 'ten'}],
    ['a negative limit', {limit: -1}],
    ['a fractional limit', {limit: 1.5}],
    ['a non-object before', {before: 'not-an-object'}],
    ['an empty sessionId', {before: {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: ''}}],
    ['an overlong sessionId', {before: {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: 'a'.repeat(129)}}],
    ['an unparseable updatedAt', {before: {updatedAt: 'not-a-date', sessionId: 's1'}}],
    ['a boolean updatedAt', {before: {updatedAt: true, sessionId: 's1'}}],
  ])('rejects %s', (_name, extra) => {
    const result = validateMessage({type: 'list_sessions', ...extra});

    expect(result.valid).toBe(false);
  });
});

